-- 古树名木表
DROP TABLE IF EXISTS tree;
CREATE TABLE tree (
    id VARCHAR(20) NOT NULL COMMENT '古树编号',
    name VARCHAR(100) NOT NULL COMMENT '古树名称',
    species VARCHAR(50) COMMENT '树种',
    age INT COMMENT '树龄',
    lat DOUBLE COMMENT '纬度',
    lon DOUBLE COMMENT '经度',
    location VARCHAR(200) COMMENT '位置描述',
    address VARCHAR(200) COMMENT '详细地址',
    protection_level VARCHAR(20) COMMENT '保护级别',
    hash_code VARCHAR(128) COMMENT '128位哈希码',
    extra_json TEXT COMMENT '扩展JSON数据',
    image_path VARCHAR(500) COMMENT '图片路径',
    PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='古树名木信息表';

